"""Empirical confirmation of the proved implication: a graph containing an
induced octahedron is not hereditary clique-Helly, because the octahedron
itself (an induced subgraph) already fails the clique-Helly property.

Random graphs rarely contain an induced octahedron by chance (the induced
subgraph on six vertices must be exactly the 4-regular K_(2,2,2)), so we PLANT an
octahedron on six vertices, attach extra vertices with random adjacency, and
check the INDUCED subgraph on the core -- which is always the octahedron and thus
always fails clique-Helly.
"""
from __future__ import annotations
import random
from itertools import combinations
from typing import Dict, FrozenSet, List, Set, Tuple

Graph = Dict[int, Set[int]]


def planted_octahedron(extra: int, p: float, seed: int) -> Graph:
    """Octahedron on {0..5} (adjacent iff different antipodal pair) plus `extra`
    randomly-attached vertices."""
    rng = random.Random(seed)
    n = 6 + extra
    g: Graph = {v: set() for v in range(n)}
    for i, j in combinations(range(6), 2):
        if i // 2 != j // 2:
            g[i].add(j)
            g[j].add(i)
    for v in range(6, n):
        for u in range(v):
            if rng.random() < p:
                g[v].add(u)
                g[u].add(v)
    return g


def induced_subgraph(g: Graph, verts: Tuple[int, ...]) -> Graph:
    s = set(verts)
    return {v: (g[v] & s) for v in verts}


def is_clique(g: Graph, s) -> bool:
    return all(v in g[u] for u, v in combinations(s, 2))


def maximal_cliques(g: Graph) -> List[FrozenSet[int]]:
    verts = list(g)
    out: List[FrozenSet[int]] = []
    for r in range(1, len(verts) + 1):
        for combo in combinations(verts, r):
            if is_clique(g, combo) and all(
                not is_clique(g, combo + (w,))
                for w in verts if w not in combo
            ):
                out.append(frozenset(combo))
    return out


def clique_helly_fails(g: Graph) -> bool:
    cliques = maximal_cliques(g)
    for k0, k1, k2 in combinations(cliques, 3):
        if (k0 & k1) and (k0 & k2) and (k1 & k2) and not (k0 & k1 & k2):
            return True
    return False


def induced_octahedron_on_core(g: Graph) -> bool:
    core = tuple(range(6))
    sub = induced_subgraph(g, core)
    if any(len(sub[v]) != 4 for v in core):
        return False
    ne = [(u, v) for u, v in combinations(core, 2) if v not in sub[u]]
    cov: Set[int] = set()
    for u, v in ne:
        cov |= {u, v}
    return len(ne) == 3 and len(cov) == 6


def main() -> None:
    trials = 150
    ok = 0
    for seed in range(trials):
        g = planted_octahedron(extra=2, p=0.5, seed=seed)
        assert induced_octahedron_on_core(g), "core must stay an induced octahedron"
        core_sub = induced_subgraph(g, tuple(range(6)))
        if clique_helly_fails(core_sub):
            ok += 1
    print(f"trials with a planted induced octahedron: {trials}")
    print(f"induced octahedron fails clique-Helly in: {ok}/{trials}")
    print("Confirms: the induced octahedron is never clique-Helly,")
    print("so the ambient graph is never hereditary clique-Helly.")


if __name__ == "__main__":
    main()

