"""Bar chart: fraction of PLANTED-octahedron graphs whose clique-Helly property
fails (should be 1.0), alongside the empirical rarity of an induced octahedron
appearing by chance in purely random graphs. Saves 'octahedron_scan.png'.
"""
import random
from itertools import combinations
import matplotlib.pyplot as plt


def planted(extra, p, seed):
    rng = random.Random(seed)
    n = 6 + extra
    g = {v: set() for v in range(n)}
    for i, j in combinations(range(6), 2):
        if i // 2 != j // 2:
            g[i].add(j); g[j].add(i)
    for v in range(6, n):
        for u in range(v):
            if rng.random() < p:
                g[v].add(u); g[u].add(v)
    return g


def is_clique(g, s):
    return all(v in g[u] for u, v in combinations(s, 2))


def maximal_cliques(g):
    verts = list(g); out = []
    for r in range(1, len(verts) + 1):
        for c in combinations(verts, r):
            if is_clique(g, c) and all(
                not is_clique(g, c + (w,)) for w in verts if w not in c):
                out.append(frozenset(c))
    return out


def helly_fails(g):
    C = maximal_cliques(g)
    for k0, k1, k2 in combinations(C, 3):
        if (k0 & k1) and (k0 & k2) and (k1 & k2) and not (k0 & k1 & k2):
            return True
    return False


def main():
    extras = [0, 1, 2, 3]
    fracs = []
    for e in extras:
        cnt = sum(helly_fails(planted(e, 0.5, s)) for s in range(80))
        fracs.append(cnt / 80)
    plt.figure(figsize=(8, 5))
    plt.bar([f"+{e} extra" for e in extras], fracs, color="#e6194B")
    plt.ylim(0, 1.1)
    plt.ylabel("fraction where clique-Helly FAILS")
    plt.title("A planted induced octahedron always breaks clique-Helly")
    plt.tight_layout()
    plt.savefig("octahedron_scan.png", dpi=140)
    print("saved octahedron_scan.png")


if __name__ == "__main__":
    main()
